script:
stage(1000, 600, "#fbfbf8");
title({hu: "Logikai kapuk – fényrendszer", en: "Logic gates – light system"});
plotWindow(20);

// ---------- Vezérlők / Controls ----------
toggle("auto", {hu: "Automatikus ciklus (00→01→10→11)", en: "Auto-cycle inputs (00→01→10→11)"}, true);
param("step", {hu: "Lépésidő (auto)", en: "Step time (auto)"}, 1, 6, 2.5, 0.5, "s");
toggle("A", {hu: "A kapcsoló (kézi, auto nélkül)", en: "Switch A (manual, auto off)"}, true);
toggle("B", {hu: "B kapcsoló (kézi, auto nélkül)", en: "Switch B (manual, auto off)"}, false);
toggle("negA", {hu: "A negálása (NOT)", en: "Negate A (NOT)"}, false);
toggle("negB", {hu: "B negálása (NOT)", en: "Negate B (NOT)"}, false);
toggle("negOut", {hu: "Minden kimenet negálása", en: "Negate all outputs"}, false);

// ---------- Adatok / Data ----------
// Jelképek: kapuk alakjelképpel (a kis kör ○ = negálás), lámpa = kör X-szel (IEC 60617).
// Symbols: distinctive-shape gate symbols (the small circle ○ = negation), lamp = circle with an X (IEC 60617).
// „a” és „b” a kapuk bemenete az A és B kapcsoló esetleges negálása UTÁN.
// "a" and "b" are the gate inputs AFTER the optional negation of the switches A and B.
const GW = 56, GH = 22;      // kapujelkép szélessége és fél magassága (px) / gate symbol width and half-height (px)
const LAMP_R = 18;           // kimeneti lámpa sugara (px) / output lamp radius (px)
const gates = [
  {name: {hu: "ÉS (AND)", en: "AND"},               f: "Y = a · b",    shape: "and", bub: false, off: 0,  two: true,  fn: (a, b) => a & b},
  {name: {hu: "NEM-ÉS (NAND)", en: "NAND"},         f: "Y = ¬(a · b)", shape: "and", bub: true,  off: 0,  two: true,  fn: (a, b) => 1 - (a & b)},
  {name: {hu: "VAGY (OR)", en: "OR"},               f: "Y = a + b",    shape: "or",  bub: false, off: 6,  two: true,  fn: (a, b) => a | b},
  {name: {hu: "NEM-VAGY (NOR)", en: "NOR"},         f: "Y = ¬(a + b)", shape: "or",  bub: true,  off: 6,  two: true,  fn: (a, b) => 1 - (a | b)},
  {name: {hu: "KIZÁRÓ VAGY (XOR)", en: "XOR"},      f: "Y = a ⊕ b",    shape: "xor", bub: false, off: -2, two: true,  fn: (a, b) => a ^ b},
  {name: {hu: "EGYENLŐSÉG (XNOR)", en: "XNOR"},     f: "Y = ¬(a ⊕ b)", shape: "xor", bub: true,  off: -2, two: true,  fn: (a, b) => 1 - (a ^ b)},
  {name: {hu: "NEM (NOT)", en: "NOT"},              f: "Y = ¬a",       shape: "not", bub: true,  off: 0,  two: false, fn: (a, b) => 1 - a}
];

// ---------- Állapot / State ----------
// automatikus ciklus: az aktuális bemeneti kombináció (0…3) és az ott töltött idő (s)
// auto-cycle: current input combination (0…3) and the time spent on it (s)
let idx = 0, tc = 0;
update(dt => {
  if (P.auto) {
    tc += dt;
    if (tc >= P.step) { tc -= P.step; idx = (idx + 1) % 4; }   // 00 → 01 → 10 → 11 → 00 …
  }
});

// ---------- Segédfüggvények (csak a draw-ból hívva) / Helpers (called from draw only) ----------
// Vezeték: szürke, ha a jel 0; narancs, mozgó nyilakkal, ha 1 (0-nál nincs nyíl)
// Wire: grey when the signal is 0, orange with moving arrows when it is 1 (no arrows at 0)
function wire(pts, v) {
  polyline(pts, {stroke: v ? C.orange : "#9aa3b2", lw: 3});
  if (v) flow(pts, {speed: 70, spacing: 50, color: "#8a3d00", line: false});
}
function junction(x, y, v) { circle(x, y, 3.5, {fill: v ? C.orange : "#9aa3b2", stroke: null}); }   // csomópont / junction dot
// Lámpa: kör X-szel; ha ég, sárga kitöltést és halvány fényudvart kap
// Lamp: circle with an X; when lit it gets a yellow fill and a soft halo
function lamp(x, y, r, on) {
  if (on) {
    circle(x, y, r + 16, {fill: "rgba(255,200,40,0.18)", stroke: null});
    circle(x, y, r + 8, {fill: "rgba(255,200,40,0.30)", stroke: null});
  }
  circle(x, y, r, {fill: on ? "#ffd23f" : "#e9e6dc", stroke: C.ink, lw: 2.5});
  line(x - r * 0.7, y - r * 0.7, x + r * 0.7, y + r * 0.7, {stroke: C.ink, lw: 2});
  line(x - r * 0.7, y + r * 0.7, x + r * 0.7, y - r * 0.7, {stroke: C.ink, lw: 2});
}
// Kis inverter (NEM) a vezetéken: háromszög + kör, teljes szélessége 27 px
// Small inverter (NOT) placed on a wire: triangle + bubble, total width 27 px
function inverter(x, y) {
  polygon([[x, y - 9], [x + 18, y], [x, y + 9]], {fill: "#fff", stroke: C.ink, lw: 2.5});
  circle(x + 22.5, y, 4.5, {fill: "#fff", stroke: C.ink, lw: 2.5});
}
// Másodfokú Bézier-görbe n+1 pontban (a görbe VAGY / KIZÁRÓ VAGY alakhoz)
// Quadratic Bézier curve sampled into n+1 points (for the curved OR / XOR shapes)
function bez(p0, p1, p2, n) {
  const out = [];
  for (let k = 0; k <= n; k++) {
    const u = k / n, m = 1 - u;
    out.push([m * m * p0[0] + 2 * m * u * p1[0] + u * u * p2[0], m * m * p0[1] + 2 * m * u * p1[1] + u * u * p2[1]]);
  }
  return out;
}
function drawGate(shape, x0, y, fillc) {
  const st = {fill: fillc, stroke: C.ink, lw: 2.5};
  if (shape === "and") {                              // egyenes hát + félkör eleje / flat back + semicircle front
    const pts = [[x0, y - GH], [x0 + GW - GH, y - GH]];
    for (let k = 1; k <= 14; k++) { const an = -PI / 2 + PI * k / 14; pts.push([x0 + GW - GH + GH * cos(an), y + GH * sin(an)]); }
    pts.push([x0, y + GH]);
    polygon(pts, st);
  } else if (shape === "or" || shape === "xor") {     // ívelt hát, csúcsos eleje / curved back, pointed front
    const top = bez([x0, y - GH], [x0 + GW * 0.55, y - GH], [x0 + GW, y], 14);
    const bot = bez([x0 + GW, y], [x0 + GW * 0.55, y + GH], [x0, y + GH], 14);
    const back = bez([x0, y + GH], [x0 + 16, y], [x0, y - GH], 10);
    polygon(top.concat(bot.slice(1), back.slice(1)), st);
    if (shape === "xor") polyline(bez([x0 - 8, y + GH], [x0 + 8, y], [x0 - 8, y - GH], 10), {stroke: C.ink, lw: 2.5});   // plusz ív / extra arc
  } else {                                            // NEM: háromszög / NOT: triangle
    polygon([[x0, y - 18], [x0 + GW, y], [x0, y + 18]], st);
  }
}

// ---------- Rajzolás / Drawing ----------
draw(t => {
  // a kapcsolók nyers értéke: az automatikus ciklusból vagy a kézi kapcsolókból
  // raw switch values: from the auto-cycle or from the manual switches
  const rawA = P.auto ? floor(idx / 2) : (P.A ? 1 : 0);
  const rawB = P.auto ? idx % 2 : (P.B ? 1 : 0);
  // a kapuk bemenete az esetleges negálás után (1-gyel vett XOR megfordítja a bitet)
  // gate inputs after the optional negation (XOR with 1 flips the bit)
  const aP = rawA ^ (P.negA ? 1 : 0), bP = rawB ^ (P.negB ? 1 : 0);
  const outs = gates.map(g => g.fn(aP, bP));                 // kapuk kimenete / gate outputs
  const fins = outs.map(v => P.negOut ? 1 - v : v);          // lámpajelek (a kimenet esetleges negálása után) / lamp signals (after the optional output negation)
  const yA = 100, yB = 150, xBusA = 170, xBusB = 130, GX = 300;
  const rowY = i => 205 + i * 58;                            // az i. kapusor függőleges közepe / vertical centre of gate row i

  // halvány meleg sáv annak a sornak a hátterében, amelynek ég a lámpája
  // soft warm band behind a row whose lamp is lit
  for (let i = 0; i < 7; i++)
    rect(8, rowY(i) - 27, 642, 54, {fill: fins[i] ? "rgba(255,214,90,0.28)" : "rgba(0,0,0,0.035)", stroke: null, radius: 10});

  // ----- A és B forrás (lámpa = a kapcsoló nyers szintje), esetleges negálással -----
  // ----- sources A and B (lamp = raw switch level) with optional negation -----
  lamp(45, yA, 14, rawA === 1);
  text("A", 45, yA - 22, {size: 16, bold: true, align: "center", color: C.ink});
  if (P.negA) { wire([[59, yA], [70, yA]], rawA); inverter(70, yA); wire([[98, yA], [xBusA, yA]], aP); }
  else wire([[59, yA], [xBusA, yA]], aP);
  lamp(45, yB, 14, rawB === 1);
  text("B", 45, yB - 22, {size: 16, bold: true, align: "center", color: C.ink});
  if (P.negB) { wire([[59, yB], [70, yB]], rawB); inverter(70, yB); wire([[98, yB], [xBusB, yB]], bP); }
  else wire([[59, yB], [xBusB, yB]], bP);

  // ----- jelsínek / signal buses (a: x = 170, b: x = 130) -----
  wire([[xBusA, yA], [xBusA, rowY(6)]], aP);
  wire([[xBusB, yB], [xBusB, rowY(5) + 10]], bP);

  // ----- a kapusorok / the gate rows -----
  for (let i = 0; i < 7; i++) {
    const g = gates[i], y = rowY(i), xin = GX + g.off;
    if (g.two) {
      wire([[xBusA, y - 10], [xin, y - 10]], aP);            // a vezeték a kapu szélénél ér véget / wires stop at the gate edge
      wire([[xBusB, y + 10], [xin, y + 10]], bP);
      junction(xBusA, y - 10, aP); junction(xBusB, y + 10, bP);
    } else {
      wire([[xBusA, y], [xin, y]], aP);
      junction(xBusA, y, aP);
    }
    drawGate(g.shape, GX, y, outs[i] ? "#fff1bf" : "#ffffff");
    if (g.bub) circle(GX + GW + 5, y, 5, {fill: "#fff", stroke: C.ink, lw: 2.5});   // negáló kör / negation bubble
    const xo = GX + GW + (g.bub ? 10 : 0);                   // a kapu kimenetének x-e / gate output x
    if (P.negOut) {                                          // esetleges inverter a lámpa előtt / optional inverter in front of the lamp
      wire([[xo, y], [385, y]], outs[i]);
      inverter(385, y);
      wire([[413, y], [452, y]], fins[i]);
    } else wire([[xo, y], [452, y]], fins[i]);
    lamp(470, y, LAMP_R, fins[i] === 1);
    text(g.name, 505, y - 3, {size: 15, bold: true, color: C.ink});
    text(g.f, 505, y + 15, {size: 12, color: C.gray});
  }

  // ----- igazságtábla (jobbra), az (a, b) aktuális kombinációja kiemelve -----
  // ----- truth table (right), the current combination of (a, b) is highlighted -----
  rect(660, 170, 325, 185, {fill: "#ffffff", stroke: C.gray, lw: 1.5, radius: 10});
  text({hu: "Igazságtábla (a, b = negálás után)", en: "Truth table (a, b = after negation)"}, 672, 192, {size: 13, bold: true, color: C.ink});
  const heads = ["a", "b", "AND", "NAND", "OR", "NOR", "XOR", "XNOR", "NOT"];
  const cx = i => 668 + 34 * i + 17;                         // oszlopközepek / column centres
  for (let i = 0; i < 9; i++) text(heads[i], cx(i), 218, {size: 10, bold: true, align: "center", baseline: "middle", color: C.gray});
  const cur = aP * 2 + bP;                                   // melyik sor aktív most / which table row is active now
  for (let r = 0; r < 4; r++) {
    const ya = 246 + r * 28, ra = floor(r / 2), rb = r % 2;
    if (r === cur) rect(665, ya - 14, 312, 28, {fill: "rgba(255,210,63,0.45)", stroke: null, radius: 6});
    const vals9 = [ra, rb].concat(gates.map(g => P.negOut ? 1 - g.fn(ra, rb) : g.fn(ra, rb)));
    for (let i = 0; i < 9; i++)
      text("" + vals9[i], cx(i), ya, {size: 15, bold: true, align: "center", baseline: "middle", color: vals9[i] ? "#d97706" : "#8b93a1"});
  }

  // ----- jelmagyarázat és élő egyenletek (jobbra lent) / legend and live equations (right, lower) -----
  lamp(682, 398, 10, true);
  text({hu: "1 = igaz\nég a lámpa, narancs vezeték", en: "1 = true\nlamp lit, orange wire"}, 702, 396, {size: 12, color: C.ink});
  lamp(682, 438, 10, false);
  text({hu: "0 = hamis\nsötét lámpa, szürke vezeték", en: "0 = false\ndark lamp, grey wire"}, 702, 436, {size: 12, color: C.ink});
  text({hu: "○ a vezetéken = negálás (NOT)\na, b = a kapuk bemenete negálás után", en: "○ on a wire = negation (NOT)\na, b = gate inputs after negation"}, 672, 478, {size: 12, color: C.gray});
  text("A = " + rawA + "  →  a = " + aP + (P.negA ? tr({hu: "  (negálva)", en: "  (negated)"}) : ""), 672, 535, {size: 13, bold: true, color: C.ink});
  text("B = " + rawB + "  →  b = " + bP + (P.negB ? tr({hu: "  (negálva)", en: "  (negated)"}) : ""), 672, 555, {size: 13, bold: true, color: C.ink});
  if (P.negOut) text({hu: "A lámpák a ¬Y értéket mutatják", en: "Lamps show ¬Y"}, 672, 575, {size: 12, color: C.red});

  // ----- mért értékek és grafikonok / readouts and graphs -----
  show({hu: "A / B (kapcsolók)", en: "A / B (switches)"}, rawA + " / " + rawB, "");
  show({hu: "a / b (negálás után)", en: "a / b (after negation)"}, aP + " / " + bP, "");
  for (let i = 0; i < 7; i++) show(gates[i].name, fins[i], "", 0);
  plot("a", aP, {color: C.blue, min: 0, max: 1, group: "in"});
  plot("b", bP, {color: C.purple, min: 0, max: 1, group: "in"});
  plot("AND", fins[0], {color: C.green, min: 0, max: 1, group: "out"});
  plot("OR", fins[2], {color: C.orange, min: 0, max: 1, group: "out"});
  plot("XOR", fins[4], {color: C.red, min: 0, max: 1, group: "out"});
  val({aP, bP});   // a Jelölők fül ezeket használhatja / available to the Markup tab
});
